    <div className="project-facts"><div><small>PRINCIPAL</small><span><Avatar user={principal} size="sm"/><strong>{principal?.name}</strong></span></div><div><small>PROJECT LEAD</small><span><Avatar user={lead} size="sm"/><strong>{lead?.name}</strong></span></div><div><small>CURRENT STAGE</small><strong>{p.currentStage}</strong></div><div><small>TARGET DEADLINE</small><strong>{p.deadlineLabel}</strong></div></div>
