  const change=(id:string,patch:Partial<ReportEntry>)=>setEntries(entries.map(e=>e.workItemId===id?{...e,...patch}:e));
  function save(){if(!entries.length)return setError('Select at least one deliverable.');if(!summary.trim())return setError('Add a short overall summary.');if(entries.some(e=>e.minutes<=0||!e.note.trim()||e.status==='Blocked'&&!e.blocker.trim()))return setError('Add a note and valid time for every selected deliverable, plus a blocker when required.');mutate(d=>updateService.createReport(d,user.id,{summary,entries:entries.map(e=>({...e,note:e.note,blocker:e.blocker||undefined}))}));close()}
