  const toggle=(id:string,setter:(ids:string[])=>void,ids:string[])=>setter(ids.includes(id)?ids.filter(x=>x!==id):[...ids,id]);
  function save(){if(mode==='new'){if(!start||!end||!direction.trim())return setError('Set the cycle dates and direction.');if(!selected.length)return setError('Select at least one deliverable.');mutate(d=>cycleService.create(d,user.id,{projectId:project.id,startDate:start,endDate:end,direction,deliverableIds:selected}));close();return}if(!cycle||!summary.trim())return setError('Add a closing summary.');if(carry.length&&!nextPlan.trim())return setError('Add next-cycle priorities.');mutate(d=>{let next=cycleService.close(d,user.id,cycle.id,summary,nextPlan);if(carry.length){const nextStart=new Date(`${cycle.endDate}T00:00:00`);nextStart.setDate(nextStart.getDate()+1);const nextEnd=new Date(nextStart);nextEnd.setDate(nextEnd.getDate()+4);next=cycleService.create(next,user.id,{projectId:project.id,startDate:nextStart.toISOString().slice(0,10),endDate:nextEnd.toISOString().slice(0,10),direction:nextPlan,deliverableIds:[]});const target=next.projects.find(p=>p.id===project.id)!.activeCycleId!;carry.forEach(id=>{next=cycleService.carryForward(next,user.id,id,target)});}return next});close()}
